# Reviews
bars3 = axes7[2].bar(['Fiction', 'Non-Fiction'], [fic_avg_reviews, nf_avg_reviews],
                      color=[C_FICTION, C_NONFICTION], width=0.5, edgecolor='white')
axes7[2].set_title('Average Reviews', fontsize=12, fontweight='bold')
axes7[2].set_ylabel('Review Count')
for bar, val in zip(bars3, [fic_avg_reviews, nf_avg_reviews]):
    axes7[2].text(bar.get_x() + bar.get_width()/2, bar.get_height() + 200,
