fig7.suptitle('Fiction vs. Non-Fiction: Head-to-Head Comparison', fontsize=14, fontweight='bold', y=1.02)
plt.tight_layout()
chart_genre_compare = fig_to_base64(fig7)


# Chart 8: Top 10 authors by appearances (horizontal bar)
top10 = author_freq.head(10)
fig8, ax8 = plt.subplots(figsize=(9, 5.5))
y_pos = range(len(top10) - 1, -1, -1)
