# Chart 9: Price segment analysis
fig9, ax9 = plt.subplots(figsize=(8, 5))
x_seg = range(len(segment_stats))
bars9 = ax9.bar(x_seg, segment_stats['count'], color=[C_MUTED, C_FICTION, C_SECONDARY, C_NONFICTION, C_PRIMARY],
