             f'{val}\n({rating:.2f}★)', ha='center', fontsize=9, fontweight='bold')
chart_price_segments = fig_to_base64(fig9)


# Chart 10: Dual-axis YoY (price + rating)
fig10, ax10a = plt.subplots(figsize=(9, 5))
ax10b = ax10a.twinx()
