# ── Data Loading ───────────────────────────────────────────────────────────────
df = pd.read_csv(DATA_PATH)
df.columns = df.columns.str.strip()
df['Genre'] = df['Genre'].str.strip()

# ── Computed Statistics ────────────────────────────────────────────────────────
total_records = len(df)
unique_books = df['Name'].nunique()
unique_authors = df['Author'].nunique()
avg_rating = df['User Rating'].mean()
avg_price = df['Price'].mean()
avg_reviews = df['Reviews'].mean()
median_price = df['Price'].median()
min_price = df['Price'].min()
max_price = df['Price'].max()
min_rating = df['User Rating'].min()
max_rating = df['User Rating'].max()

# Genre splits
fiction_df = df[df['Genre'] == 'Fiction']
nonfiction_df = df[df['Genre'] == 'Non Fiction']
fic_count = len(fiction_df)
nf_count = len(nonfiction_df)
fic_pct = fic_count / total_records * 100
nf_pct = nf_count / total_records * 100

fic_avg_price = fiction_df['Price'].mean()
nf_avg_price = nonfiction_df['Price'].mean()
fic_avg_rating = fiction_df['User Rating'].mean()
nf_avg_rating = nonfiction_df['User Rating'].mean()
fic_avg_reviews = fiction_df['Reviews'].mean()
nf_avg_reviews = nonfiction_df['Reviews'].mean()
fic_median_price = fiction_df['Price'].median()
nf_median_price = nonfiction_df['Price'].median()

# Pearson correlation (price vs rating)
pearson_r, pearson_p = stats.pearsonr(df['Price'], df['User Rating'])

# By-genre Pearson
fic_r, fic_p = stats.pearsonr(fiction_df['Price'], fiction_df['User Rating'])
nf_r, nf_p = stats.pearsonr(nonfiction_df['Price'], nonfiction_df['User Rating'])

# Year-over-year stats
yearly = df.groupby('Year').agg(
    avg_price=('Price', 'mean'),
    avg_rating=('User Rating', 'mean'),
    avg_reviews=('Reviews', 'mean'),
    count=('Name', 'count')
).reset_index()

yearly_fic = fiction_df.groupby('Year').agg(
    avg_price=('Price', 'mean'),
    avg_rating=('User Rating', 'mean'),
    avg_reviews=('Reviews', 'mean'),
).reset_index()

yearly_nf = nonfiction_df.groupby('Year').agg(
    avg_price=('Price', 'mean'),
    avg_rating=('User Rating', 'mean'),
    avg_reviews=('Reviews', 'mean'),
).reset_index()

# Year-over-year changes
yearly['price_yoy'] = yearly['avg_price'].pct_change() * 100
yearly['rating_yoy'] = yearly['avg_rating'].pct_change() * 100

# Top authors by bestseller frequency
author_freq = df.groupby('Author').agg(
    appearances=('Name', 'count'),
    avg_rating=('User Rating', 'mean'),
    avg_price=('Price', 'mean'),
    avg_reviews=('Reviews', 'mean'),
    unique_books=('Name', 'nunique')
).sort_values('appearances', ascending=False).head(15).reset_index()

# Price segments
def price_segment(p):
    if p == 0:
        return 'Free ($0)'
    elif p <= 8:
        return 'Budget ($1–$8)'
    elif p <= 15:
        return 'Mid-Range ($9–$15)'
    elif p <= 25:
        return 'Premium ($16–$25)'
    else:
        return 'High-End ($26+)'

df['Price Segment'] = df['Price'].apply(price_segment)
segment_order = ['Free ($0)', 'Budget ($1–$8)', 'Mid-Range ($9–$15)', 'Premium ($16–$25)', 'High-End ($26+)']
segment_stats = df.groupby('Price Segment').agg(
    count=('Name', 'count'),
    avg_rating=('User Rating', 'mean'),
    avg_reviews=('Reviews', 'mean')
).reindex(segment_order).reset_index()

# ── Chart Generation ───────────────────────────────────────────────────────────

def fig_to_base64(fig, dpi=130):
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=dpi, bbox_inches='tight', facecolor='white')
    plt.close(fig)
    buf.seek(0)
    return base64.b64encode(buf.read()).decode('utf-8')


