ax1.set_title('Genre Distribution Across All Bestseller Years', fontsize=13, fontweight='bold')
chart_genre_pie = fig_to_base64(fig1)


# Chart 2: Price vs Rating Scatter with trend line
fig2, ax2 = plt.subplots(figsize=(8, 5.5))
# Sample to avoid overplotting for very dense areas
np.random.seed(42)
jitter_y = np.random.normal(0, 0.03, size=len(df))
ax2.scatter(df['Price'], df['User Rating'] + jitter_y,
            alpha=0.45, s=40, color=C_SECONDARY, edgecolors='white', linewidth=0.3, label='Individual titles')
# Trend line
z = np.polyfit(df['Price'], df['User Rating'], 1)
p = np.poly1d(z)
x_line = np.linspace(df['Price'].min(), df['Price'].max(), 100)
ax2.plot(x_line, p(x_line), '--', color=C_DANGER, linewidth=2, label=f'Trend (r = {pearson_r:.3f})')
ax2.set_xlabel('Price ($)')
ax2.set_ylabel('User Rating')
ax2.set_title(f'Price vs. User Rating — Pearson r = {pearson_r:.3f}, p = {pearson_p:.4f}', fontsize=13, fontweight='bold')
ax2.legend(loc='lower left', framealpha=0.9)
ax2.set_ylim(3.0, 5.15)
ax2.yaxis.set_major_formatter(mticker.FormatStrFormatter('%.1f'))
chart_scatter = fig_to_base64(fig2)


# Chart 3: Genre comparison scatter overlays
fig3, ax3 = plt.subplots(figsize=(8, 5.5))
jitter_fic = np.random.normal(0, 0.03, size=len(fiction_df))
jitter_nf = np.random.normal(0, 0.03, size=len(nonfiction_df))
ax3.scatter(fiction_df['Price'], fiction_df['User Rating'] + jitter_fic,
            alpha=0.45, s=40, color=C_FICTION, edgecolors='white', linewidth=0.3, label='Fiction')
ax3.scatter(nonfiction_df['Price'], nonfiction_df['User Rating'] + jitter_nf,
            alpha=0.45, s=40, color=C_NONFICTION, edgecolors='white', linewidth=0.3, label='Non-Fiction')
# Trend lines per genre
for gdf, color, label in [(fiction_df, C_FICTION, 'Fiction'), (nonfiction_df, C_NONFICTION, 'Non-Fiction')]:
    zg = np.polyfit(gdf['Price'], gdf['User Rating'], 1)
    pg = np.poly1d(zg)
    xg = np.linspace(gdf['Price'].min(), gdf['Price'].max(), 100)
    ax3.plot(xg, pg(xg), '--', color=color, linewidth=2)
ax3.set_xlabel('Price ($)')
ax3.set_ylabel('User Rating')
ax3.set_title('Price vs. Rating by Genre', fontsize=13, fontweight='bold')
ax3.legend(loc='lower left', framealpha=0.9)
ax3.set_ylim(3.0, 5.15)
chart_scatter_genre = fig_to_base64(fig3)


# Chart 4: Year-over-Year Average Price
fig4, ax4 = plt.subplots(figsize=(9, 5))
ax4.plot(yearly['Year'], yearly['avg_price'], 'o-', color=C_PRIMARY, linewidth=2.5, markersize=8, label='Overall')
