nf_r, nf_p = stats.pearsonr(nonfiction_df['Price'], nonfiction_df['User Rating'])

# Year-over-year stats
yearly = df.groupby('Year').agg(
    avg_price=('Price', 'mean'),
    avg_rating=('User Rating', 'mean'),
    avg_reviews=('Reviews', 'mean'),
    count=('Name', 'count')
).reset_index()

