).reset_index()

# Year-over-year changes
yearly['price_yoy'] = yearly['avg_price'].pct_change() * 100
yearly['rating_yoy'] = yearly['avg_rating'].pct_change() * 100

# Top authors by bestseller frequency
author_freq = df.groupby('Author').agg(
    appearances=('Name', 'count'),
